/* 第一章完整材料题库（续）。 */
TS('c1-01','1.1','三角形概念、基本要素与按角分类',
 '三角形由不在同一直线上的三条线段首尾顺次相接组成；任意三角形都有三个顶点、三条边、三个内角。按角可分为锐角、直角、钝角三角形。',
 '判断图形是否为三角形先看三条线段是否首尾顺次相接并封闭；数三角形时按公共边或第三个顶点逐一枚举。',
 '三条线段相交不等于构成三角形；按角分类时看最大角。',
 C1('c1-1-1','1.1 巩固训练1 第1题','选择题','下面是一位同学用三根木棒拼成的四个图形，其中符合三角形概念的是（　）。','D',['三角形必须由不在同一直线上的三条线段首尾顺次相接组成封闭图形。','图 D 满足定义。'],['A','B','C','D'],'c1-1-1',{alsoQuestion:true}),
 C1('c1-1-2','1.1 巩固训练1 第2题','选择题','如图所示，以 BC 为边的三角形共有（　）。','C',['以 BC 为公共边，第三个顶点分别可以取 A、D、E。','所以共有 3 个。'],['1个','2个','3个','4个'],'c1-1-2'),
 C1('c1-1-3','1.1 巩固训练1 第3题','填空题','如图所示，图中有____个三角形，以 AD 为边的三角形有____。','3；△ABD、△ADC',['图中有 △ABC、△ABD、△ADC，共 3 个。','以 AD 为边的是 △ABD、△ADC。'],[],'c1-1-3'),
 C1('c1-1-4','1.1 巩固训练1 第4题','选择题','三角形按角分类可以分为（　）。','A',['按角分类分为锐角三角形、直角三角形、钝角三角形。'],['锐角三角形、直角三角形、钝角三角形','等腰三角形、等边三角形、不等边三角形','直角三角形、等腰直角三角形','以上答案都不正确'])
);

TS('t02','1.1','内角和、直角三角形的性质与判定',
 '三角形内角和为 180°；直角三角形两个锐角互余。有一个角为 90°，或有两个角互余，可以判定三角形为直角三角形。',
 '先找平行线、直角或已知角关系，再使用内角和；直角三角形中优先使用两锐角互余。',
 '“两个角互余”作为直角三角形性质时要确认它们属于同一个直角三角形。',
 C1('c1-1-5','1.1 巩固训练1 第5题','选择题','如图，分别过 △ABC 的顶点 A、B 作 AD∥BE。若 ∠CAD=25°，∠EBC=80°，则 ∠ACB 的度数为（　）。','B',['由 AD∥BE，得 ∠ADC=∠EBC=80°。','在 △ACD 中，∠ACB=180°−25°−80°=75°。'],['65°','75°','85°','95°'],'c1-1-5',{alsoQuestion:true}),
 C1('c1-1-6','1.1 巩固训练1 第6题','填空题','一个三角形的三个内角度数之比为 1∶2∶7，则这个三角形中最小内角的度数是____。','18°',['设最小角为 x°，则 x+2x+7x=180°。','解得 x=18°。']),
 C1('c1-1-7','1.1 巩固训练1 第7题','选择题','若 △ABC 的三个内角度数之比为 3∶5∶2，则 △ABC 是（　）。','C',['设三个内角为 3x、5x、2x，则 10x=180°，x=18°。','最大角 5x=90°，所以是直角三角形。'],['不能确定三角形的形状','锐角三角形','直角三角形','钝角三角形']),
 C1('c1-1-8','1.1 巩固训练1 第8题','选择题','如图，在 Rt△ABC 中，∠C=90°，∠BDE=∠A，则 △BDE 为（　）。','B',['在 Rt△ABC 中，∠A+∠B=90°。','∠BDE=∠A，所以 ∠BDE+∠B=90°，从而 ∠DEB=90°。'],['锐角三角形','直角三角形','钝角三角形','以上均有可能'],'c1-1-8')
);

TS('c1-02','1.1','按边分类与等腰三角形',
 '按边可分为不等边三角形和等腰三角形；等边三角形是特殊的等腰三角形。一个三角形可同时属于按边、按角两种分类。',
 '先根据相等边判断按边分类；若有比例和周长，设比例系数列方程。',
 '等腰、等边属于按边分类，锐角、直角、钝角属于按角分类，两个标准不能混淆。',
 C1('c1-2-1','1.1 巩固训练2 第1题','选择题','等边三角形是（　）。','B',['等边三角形三个内角都是 60°，所以是锐角三角形。'],['直角三角形','锐角三角形','钝角三角形','等腰直角三角形'],null,{alsoQuestion:true}),
 C1('c1-2-2','1.1 巩固训练2 第2题','选择题','三角形按边分类可以用集合来表示，如图所示，图中小椭圆圈里的 A 表示（　）。','D',['等边三角形是等腰三角形的特殊情形，因此小椭圆 A 表示等边三角形。'],['直角三角形','锐角三角形','钝角三角形','等边三角形'],'c1-2-2'),
 C1('c1-2-3','1.1 巩固训练2 第3题','选择题','四个三角形都有一部分被遮挡，其中不能判断三角形类型的是（　）。','C',['A 可由两个已知角求第三角；B 已露出直角；D 已露出钝角。','C 只露出一个锐角，另外两个角未知，不能判断。'],['A','B','C','D'],'c1-2-3'),
 C1('c1-2-4','1.1 巩固训练2 第4题','填空题','若三角形的三边之比为 2∶3∶3，周长为 32 cm，则三边长分别为____；按边分，这个三角形是____三角形。','8 cm、12 cm、12 cm；等腰',['设三边为 2x、3x、3x，则 8x=32，x=4。','三边为 8、12、12，有两边相等，所以是等腰三角形。'])
);

TS('t01','1.1','三角形三边关系与应用',
 '三角形任意两边之和大于第三边、任意两边之差小于第三边。已知 a>b 时，第三边 c 满足 a−b<c<a+b。',
 '已知两边先写第三边的严格范围；等腰三角形要分类讨论已知边是腰还是底边，并检验三边关系。',
 '边界不能取等号；求出候选边长后必须再次检验是否能组成三角形。',
 C1('c1-e-triangle-check','1.1 三边关系知识讲解例题','解答题','判断下列线段能否组成三角形：（1）3，4，5；（2）2，2，4；（3）1，4，5；（4）2，3，6。','（1）能；（2）（3）（4）不能',['只需比较最小两边之和与最大边。','3+4>5，所以（1）能组成；2+2=4、1+4=5、2+3<6，所以其余不能组成。'],[],null,{alsoQuestion:true}),
 C1('c1-2-5','1.1 巩固训练2 第5题','选择题','等腰三角形的一边长为 6，另一边长为 13，则它的周长为（　）。','C',['若 6 为腰，则 6+6<13，不能组成三角形。','若 13 为腰，三边为 13、13、6，周长为 32。'],['25','25或32','32','19']),
 C1('c1-2-6','1.1 巩固训练2 第6题','选择题','小芳有两根长度为 6 cm 和 9 cm 的木条，她想钉一个三角形木框，第三根木条应选择（　）。','C',['设第三边为 x，则 3<x<15。','选项中只有 12 cm 满足。'],['2 cm','3 cm','12 cm','15 cm']),
 C1('c1-2-7','1.1 巩固训练2 第7题','选择题','等腰三角形周长为 21 cm，如果一边长为 5 cm，那么另两边长为（　）。','B',['若 5 为腰，底边为 11，但 5+5<11，不成立。','若 5 为底边，两腰各为 8，成立。'],['5，8','8，8','5，11','11，11']),
 C1('c1-2-8','1.1 巩固训练2 第8题','填空题','已知三角形三边长分别是 3、x、9，则 |x−5|+|x−13|=____。','8',['由三边关系得 6<x<12。','所以 x−5>0，x−13<0，原式=(x−5)+(13−x)=8。']),
 C1('c1-2-9','1.1 巩固训练2 第9题','填空题','已知 a、b、c 为三角形三边，则 a+b+c____2a（填“>”“=”或“<”）。','>',['由 b+c>a，两边同时加 a，得 a+b+c>2a。']),
 C1('c1-2-10','1.1 巩固训练2 第10题','填空题','已知 a、b、c 是 △ABC 的三边长，(b−2)²+|c−3|=0，且 a 为方程 |x−4|=2 的解，则 △ABC 的周长为____。','7',['由非负数之和为 0，得 b=2、c=3。','|x−4|=2 得 a=2 或 6；三边关系要求 1<a<5，所以 a=2。','周长为 2+2+3=7。'])
);

TS('c1-03','1.1','角平分线与角度关系',
 '三角形的角平分线是从顶点到对边的线段，把一个内角分成两个相等的角；三条内角平分线交于三角形内部的内心。',
 '看到多组相等的小角时，用角的和差判断某条射线是否平分更大的角；直角三角形两锐角互余。',
 '三角形角平分线是线段，单独一个角的平分线是射线。',
 C1('c1-3-1','1.1 巩固训练3 第1题','选择题','如图所示，∠1=∠2，∠3=∠4。判断：①AD 平分∠BAF；②AF 平分∠BAC；③AE 平分∠DAF；④AF 平分∠DAC；⑤AE 平分∠BAC。正确的有（　）。','C',['由 ∠1=∠2，AE 平分 ∠DAF，③正确。','由 ∠3=∠4 且 ∠1=∠2，得 ∠BAE=∠EAC，所以 AE 平分 ∠BAC，⑤正确。','共有 2 个正确结论。'],['4个','3个','2个','1个'],'c1-3-1',{alsoQuestion:true}),
 C1('c1-3-2','1.1 巩固训练3 第2题','选择题','直角三角形的两锐角平分线相交成的角的度数是（　）。','C',['设两个锐角为 B、C，则 B+C=90°，两角平分线在小三角形中的两个角和为 45°。','因此交点处内部角为 135°，与它相邻的角为 45°。'],['45°','135°','45°或135°','以上答案均不对'])
);
